import SwiftUI

/// Author's Circle: the community as people, not documents. Everyone sits
/// still around a ring — portrait when the contact record has one,
/// initials otherwise — in the system's own colors. Click a person and
/// their correspondence appears: lines in the label color to the authors
/// they have replied to, gray lines from the authors who have replied,
/// commented, or otherwise written in relation to them. ⌘A selects
/// everyone and shows the whole mesh. The more documents behind a line,
/// the thicker it runs; rest the pointer on a line and a card lists the
/// documents behind it — the card stays put so any of them can be clicked
/// open. Click empty space to dismiss it.
struct AuthorsCircleView: View {
    @Environment(AppModel.self) private var model
    @State private var selectedAuthor: String?
    @State private var allSelected = false
    /// The line whose documents are on display; set by hover, kept until
    /// another line takes over, the background is clicked, or the
    /// selection changes.
    @State private var activeEdgeID: String?
    /// Where the card sits: frozen at the point the line was first
    /// hovered, so it doesn't chase the pointer.
    @State private var panelPoint: CGPoint = .zero

    private struct AuthorNode: Identifiable {
        let name: String
        let documents: Int
        var id: String { name }
    }

    /// One directed line: documents by `from` that link to documents by
    /// `to` — the documents themselves ride along for the hover card.
    private struct Edge: Identifiable {
        let from: String
        let to: String
        let docs: [LiquidDoc]
        var id: String { "\(from)→\(to)" }
    }

    /// A drawn line, ready for stroking and for pointer hit-testing.
    private struct Segment {
        let edge: Edge
        let a: CGPoint
        let b: CGPoint
    }

    var body: some View {
        let authors = authors
        if authors.count < 2 {
            ContentUnavailableView(
                "Not Enough Authors",
                systemImage: "person.2",
                description: Text("Author's Circle appears once the library holds letters from at least two people."))
        } else {
            circle(authors: authors)
        }
    }

    private func circle(authors: [AuthorNode]) -> some View {
        GeometryReader { geometry in
            let positions = positions(for: authors, in: geometry.size)
            let segments = segments(in: positions)
            ZStack {
                Canvas { context, _ in
                    for segment in segments {
                        stroke(segment, in: &context)
                    }
                }
                .allowsHitTesting(false)

                ForEach(authors) { author in
                    authorButton(author)
                        .position(positions[author.name] ?? .zero)
                }

                if selectedAuthor == nil && !allSelected {
                    Text("Click an author to see their circle — ⌘A for everyone.")
                        .font(.callout)
                        .foregroundStyle(.secondary)
                        .allowsHitTesting(false)
                }

                if let segment = segments.first(where: { $0.edge.id == activeEdgeID }) {
                    edgePanel(segment.edge, in: geometry.size)
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .contentShape(Rectangle())
            .onTapGesture { activeEdgeID = nil }
            .onContinuousHover { phase in
                guard case .active(let point) = phase else { return }
                if let hit = nearestSegment(to: point, in: segments),
                   hit.edge.id != activeEdgeID {
                    activeEdgeID = hit.edge.id
                    panelPoint = point
                }
                // Off every line the card stays: it must survive the
                // pointer's journey onto it.
            }
            // ⌘A, without needing focus: an unseen button carries the
            // standard Select All shortcut for this view.
            .background(
                Button("") { selectEveryone() }
                    .keyboardShortcut("a", modifiers: .command)
                    .opacity(0)
                    .frame(width: 0, height: 0)
            )
        }
        .background(Color(nsColor: .windowBackgroundColor))
    }

    private func selectEveryone() {
        allSelected = true
        selectedAuthor = nil
        activeEdgeID = nil
    }

    private func authorButton(_ author: AuthorNode) -> some View {
        let isSelected = author.name == selectedAuthor || allSelected
        return Button {
            if selectedAuthor == author.name {
                selectedAuthor = nil
            } else {
                selectedAuthor = author.name
            }
            allSelected = false
            activeEdgeID = nil
        } label: {
            VStack(spacing: 3) {
                PersonAvatarView(name: author.name, size: 44)
                    .overlay(
                        RoundedRectangle(cornerRadius: 44 * 0.18, style: .continuous)
                            .strokeBorder(isSelected ? Color.accentColor : .clear, lineWidth: 2.5)
                    )
                Text(author.name)
                    .font(.caption2)
                    .fontWeight(author.name == selectedAuthor ? .bold : .regular)
                    .lineLimit(1)
                    .frame(maxWidth: 90)
            }
        }
        .buttonStyle(.plain)
        .help("\(author.name) — \(author.documents) documents")
    }

    /// The card behind a line: who to whom, and every document that made
    /// it — each one clickable. It stays until another line is hovered,
    /// the background is clicked, or the selection changes.
    private func edgePanel(_ edge: Edge, in size: CGSize) -> some View {
        let limit = 10
        return VStack(alignment: .leading, spacing: 4) {
            HStack {
                Text("\(edge.from) → \(edge.to)")
                    .font(.caption.weight(.semibold))
                Spacer()
                Button {
                    activeEdgeID = nil
                } label: {
                    Image(systemName: "xmark.circle.fill")
                        .foregroundStyle(.secondary)
                }
                .buttonStyle(.plain)
                .help("Dismiss")
            }
            ForEach(edge.docs.prefix(limit), id: \.id) { doc in
                Button {
                    model.openInLibrary(doc)
                } label: {
                    Text(doc.title)
                        .font(.caption)
                        .lineLimit(1)
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
                .help("Open “\(doc.title)”")
            }
            if edge.docs.count > limit {
                Text("and \(edge.docs.count - limit) more")
                    .font(.caption2)
                    .foregroundStyle(.secondary)
            }
        }
        .padding(10)
        .frame(width: 280, alignment: .leading)
        .background(.regularMaterial, in: RoundedRectangle(cornerRadius: 8))
        .shadow(radius: 4)
        .position(x: min(max(panelPoint.x, 150), size.width - 150),
                  y: max(panelPoint.y - 60, 70))
    }

    // MARK: Data

    /// Everyone with documents in the visible library, most prolific first.
    private var authors: [AuthorNode] {
        let byAuthor = Dictionary(grouping: model.filteredEntries, by: { $0.doc.creditedAuthor })
        return byAuthor
            .map { AuthorNode(name: $0.key, documents: $0.value.count) }
            .sorted { ($0.documents, $1.name) > ($1.documents, $0.name) }
    }

    /// Every directed author-to-author line in the visible library: the
    /// documents by `from` that link to documents by `to`, newest first.
    /// A document counts toward a line once.
    private var allEdges: [Edge] {
        let entries = model.filteredEntries
        let authorOf: [String: String] = Dictionary(
            uniqueKeysWithValues: entries.map { ($0.doc.id, $0.doc.creditedAuthor) })
        var docsByPair: [String: (from: String, to: String, docs: [LiquidDoc])] = [:]
        for entry in entries {
            let doc = entry.doc
            let counterparts = Set(doc.links.compactMap { link -> String? in
                guard !LiquidAddress.isPersonAddress(link.to),
                      let target = authorOf[LiquidAddress.canonical(link.to)],
                      target != doc.author else { return nil }
                return target
            })
            for counterpart in counterparts {
                let key = "\(doc.author)→\(counterpart)"
                docsByPair[key, default: (doc.author, counterpart, [])].docs.append(doc)
            }
        }
        return docsByPair.values.map { pair in
            Edge(from: pair.from, to: pair.to,
                 docs: pair.docs.sorted { $0.listedDate > $1.listedDate })
        }
    }

    /// What is on display: everything when everyone is selected, else the
    /// selected author's correspondence in both directions.
    private var visibleEdges: [Edge] {
        if allSelected { return allEdges }
        guard let selected = selectedAuthor else { return [] }
        return allEdges.filter { $0.from == selected || $0.to == selected }
    }

    // MARK: Geometry

    private func positions(for authors: [AuthorNode], in size: CGSize) -> [String: CGPoint] {
        let radius = min(size.width, size.height) / 2 - 70
        let center = CGPoint(x: size.width / 2, y: size.height / 2)
        var positions: [String: CGPoint] = [:]
        for (index, author) in authors.enumerated() {
            // Start at the top; no rotation — the circle holds still.
            let angle = -Double.pi / 2 + 2 * .pi * Double(index) / Double(authors.count)
            positions[author.name] = CGPoint(x: center.x + radius * cos(angle),
                                             y: center.y + radius * sin(angle))
        }
        return positions
    }

    /// The lines to draw right now, pulled back from the portraits and
    /// nudged sideways so the two directions between the same pair stay
    /// distinguishable.
    private func segments(in positions: [String: CGPoint]) -> [Segment] {
        visibleEdges.compactMap { edge in
            guard let from = positions[edge.from], let to = positions[edge.to] else { return nil }
            let d = hypot(to.x - from.x, to.y - from.y)
            guard d > 1 else { return nil }
            let unit = CGPoint(x: (to.x - from.x) / d, y: (to.y - from.y) / d)
            let normal = CGPoint(x: -unit.y, y: unit.x)
            let side: CGFloat = edge.from < edge.to ? 3 : -3
            let margin: CGFloat = 30
            let a = CGPoint(x: from.x + unit.x * margin + normal.x * side,
                            y: from.y + unit.y * margin + normal.y * side)
            let b = CGPoint(x: to.x - unit.x * margin + normal.x * side,
                            y: to.y - unit.y * margin + normal.y * side)
            return Segment(edge: edge, a: a, b: b)
        }
    }

    private func nearestSegment(to point: CGPoint, in segments: [Segment]) -> Segment? {
        var best: (segment: Segment, distance: CGFloat)?
        for segment in segments {
            let d = distance(from: point, toSegment: segment.a, segment.b)
            if d < 7, d < (best?.distance ?? .infinity) {
                best = (segment, d)
            }
        }
        return best?.segment
    }

    private func distance(from p: CGPoint, toSegment a: CGPoint, _ b: CGPoint) -> CGFloat {
        let ab = CGPoint(x: b.x - a.x, y: b.y - a.y)
        let lengthSquared = ab.x * ab.x + ab.y * ab.y
        guard lengthSquared > 0 else { return hypot(p.x - a.x, p.y - a.y) }
        let t = max(0, min(1, ((p.x - a.x) * ab.x + (p.y - a.y) * ab.y) / lengthSquared))
        return hypot(p.x - (a.x + ab.x * t), p.y - (a.y + ab.y * t))
    }

    // MARK: Drawing

    private func stroke(_ segment: Segment, in context: inout GraphicsContext) {
        var path = Path()
        path.move(to: segment.a)
        path.addLine(to: segment.b)
        let isActive = segment.edge.id == activeEdgeID
        // Weight carries the count; the colors stay the system's. With one
        // author selected, their replies run in the label color and what
        // comes toward them in gray; with everyone selected the mesh is
        // uniform.
        let width = 1 + min(CGFloat(segment.edge.docs.count), 7) + (isActive ? 1.5 : 0)
        let color: Color = if let selected = selectedAuthor, segment.edge.from == selected {
            .primary.opacity(isActive ? 1 : 0.8)
        } else if selectedAuthor != nil {
            .gray.opacity(isActive ? 0.95 : 0.55)
        } else {
            .primary.opacity(isActive ? 0.9 : 0.45)
        }
        context.stroke(path, with: .color(color), lineWidth: width)
    }
}

extension AuthorsCircleView {
    /// Author's Circle as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "authors-circle",
        name: "Author's Circle",
        systemImage: "person.crop.circle.badge.checkmark",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(AuthorsCircleView()) },
        hidesDocumentList: true
    )
}

connections.source:
import SwiftUI

/// The connected-documents view: an ego-centered radial map of the web
/// around the current document. Documents are cards, connections are typed
/// colored edges with direction. Click a card to re-center, double-click to
/// read it, click an edge's dot to read that pair in transpointing view.
struct DocumentWebView: View {
    @Environment(AppModel.self) private var model

    private var centerID: String? {
        if let id = model.current?.doc.id, model.index.byID[id] != nil { return id }
        return model.index.timeline.last?.id
    }

    private var web: DocumentWeb? {
        guard let centerID else { return nil }
        return WebBuilder.web(centeredOn: centerID,
                              byID: model.index.byID,
                              backlinks: model.index.backlinks)
    }

    @State private var isOpenView = false

    var body: some View {
        Group {
            if let web {
                if isOpenView {
                    WebSpaceView(docs: spaceDocs(for: web))
                } else {
                    mapView(for: web)
                }
            } else {
                ContentUnavailableView(
                    "No Documents",
                    systemImage: "point.3.connected.trianglepath.dotted",
                    description: Text("Open a document, or add documents to the community folder.")
                )
            }
        }
        .toolbar {
            ToolbarItem {
                Picker("View", selection: $isOpenView) {
                    Text("Closed").tag(false)
                    Text("Open").tag(true)
                }
                .pickerStyle(.segmented)
                .help("Closed: a map of connected documents. Open: the documents themselves as columns, with lines to the exact cited passages.")
            }
        }
    }

    /// The center and its direct connections, as full documents for the
    /// open (columns-in-space) view.
    private func spaceDocs(for web: DocumentWeb) -> [LiquidDoc] {
        let center = web.nodes.first { $0.ring == 0 }.map { [$0.entry.doc] } ?? []
        let ringOne = web.nodes.filter { $0.ring == 1 }.prefix(4).map { $0.entry.doc }
        return center + ringOne
    }

    private func mapView(for web: DocumentWeb) -> some View {
        GeometryReader { proxy in
            let positions = layout(web: web, in: proxy.size)
            ZStack {
                edgeLayer(web: web, positions: positions)
                ghostLayer(web: web, positions: positions)
                edgeDotLayer(web: web, positions: positions)
                ForEach(web.nodes) { node in
                    card(for: node)
                        .position(positions[node.id]
                                  ?? CGPoint(x: proxy.size.width / 2, y: proxy.size.height / 2))
                }
            }
        }
        .overlay(alignment: .bottom) { legend(for: web) }
    }

    // MARK: - Layout

    private func layout(web: DocumentWeb, in size: CGSize) -> [String: CGPoint] {
        var positions: [String: CGPoint] = [:]
        let center = CGPoint(x: size.width / 2, y: size.height / 2)
        positions[web.centerID] = center
        let radiusOne = min(size.width, size.height) * 0.30
        let radiusTwo = min(size.width, size.height) * 0.46

        func point(angle: Double, radius: CGFloat) -> CGPoint {
            CGPoint(x: center.x + radius * CGFloat(cos(angle)),
                    y: center.y + radius * CGFloat(sin(angle)))
        }

        let ringOne = web.nodes.filter { $0.ring == 1 }
        let slots = ringOne.count + web.unresolvedTargets.count
        var angleByID: [String: Double] = [:]
        if slots > 0 {
            for (index, node) in ringOne.enumerated() {
                let angle = -Double.pi / 2 + Double(index) * 2 * .pi / Double(slots)
                positions[node.id] = point(angle: angle, radius: radiusOne)
                angleByID[node.id] = angle
            }
            for (offset, ghost) in web.unresolvedTargets.enumerated() {
                let index = ringOne.count + offset
                let angle = -Double.pi / 2 + Double(index) * 2 * .pi / Double(slots)
                positions["ghost:\(ghost)"] = point(angle: angle, radius: radiusOne)
            }
        }

        // Ring two fans out around its parent's angle.
        let grouped = Dictionary(grouping: web.nodes.filter { $0.ring == 2 },
                                 by: { $0.parentID ?? "" })
        for (parentID, children) in grouped {
            let base = angleByID[parentID] ?? (-Double.pi / 2)
            let step = 0.34
            for (index, child) in children.enumerated() {
                let offset = (Double(index) - Double(children.count - 1) / 2) * step
                positions[child.id] = point(angle: base + offset, radius: radiusTwo)
            }
        }
        return positions
    }

    // MARK: - Layers

    private func edgeLayer(web: DocumentWeb, positions: [String: CGPoint]) -> some View {
        ForEach(web.edges) { edge in
            if let from = positions[edge.fromID], let to = positions[edge.toID],
               let path = Self.edgePath(from: from, to: to) {
                path.stroke(RelStyle.color(for: edge.rel).opacity(0.55),
                            style: StrokeStyle(lineWidth: 1.8, lineCap: .round, lineJoin: .round))
            }
        }
    }

    private func ghostLayer(web: DocumentWeb, positions: [String: CGPoint]) -> some View {
        ForEach(web.unresolvedTargets, id: \.self) { target in
            if let ghostPosition = positions["ghost:\(target)"],
               let from = positions[web.centerID] {
                ZStack {
                    if let path = Self.edgePath(from: from, to: ghostPosition) {
                        path.stroke(Color.secondary.opacity(0.4),
                                    style: StrokeStyle(lineWidth: 1.4, dash: [4, 3]))
                    }
                }
                Text(target)
                    .font(.caption2.monospaced())
                    .lineLimit(1)
                    .truncationMode(.middle)
                    .foregroundStyle(.tertiary)
                    .padding(.horizontal, 8)
                    .padding(.vertical, 5)
                    .frame(width: 120)
                    .overlay(
                        RoundedRectangle(cornerRadius: 7)
                            .stroke(Color.secondary.opacity(0.4),
                                    style: StrokeStyle(lineWidth: 1, dash: [4, 3]))
                    )
                    .position(ghostPosition)
                    .help("Cited by the center document but not in the community folder yet")
            }
        }
    }

    private func edgeDotLayer(web: DocumentWeb, positions: [String: CGPoint]) -> some View {
        ForEach(web.edges) { edge in
            if let from = positions[edge.fromID], let to = positions[edge.toID] {
                let jitter = CGFloat(edge.ordinal % 3 - 1) * 7
                Button {
                    openPair(edge)
                } label: {
                    Circle()
                        .fill(RelStyle.color(for: edge.rel))
                        .frame(width: 9, height: 9)
                        .overlay(Circle().strokeBorder(.background, lineWidth: 1.5))
                        .padding(6)   // generous click target
                        .contentShape(Circle())
                }
                .buttonStyle(.plain)
                .position(x: (from.x + to.x) / 2 + jitter, y: (from.y + to.y) / 2 + jitter)
                .help("\(edge.rel ?? "link") — click to read both in parallel")
            }
        }
    }

    // MARK: - Cards

    private func card(for node: DocumentWeb.Node) -> some View {
        VStack(spacing: 2) {
            Text(node.entry.doc.title)
                .font(.system(size: node.ring == 0 ? 14 : 12, design: .serif))
                .multilineTextAlignment(.center)
                .lineLimit(2)
            Text(node.entry.doc.displayAuthor)
                .font(.system(size: 9))
                .foregroundStyle(.secondary)
                .lineLimit(1)
        }
        .padding(.horizontal, 10)
        .padding(.vertical, 6)
        .frame(width: node.ring == 0 ? 170 : 140)
        .background(.thickMaterial, in: RoundedRectangle(cornerRadius: 8))
        .overlay(
            RoundedRectangle(cornerRadius: 8)
                .stroke(node.ring == 0 ? Color.accentColor : Color.secondary.opacity(0.35),
                        lineWidth: node.ring == 0 ? 2 : 1)
        )
        .opacity(node.ring == 2 ? 0.82 : 1)
        .gesture(
            TapGesture(count: 2)
                .onEnded { model.openInLibrary(node.entry.doc) }
                .exclusively(before: TapGesture().onEnded {
                    if node.ring != 0 { model.open(node.entry.doc) }
                })
        )
        .help(node.ring == 0
              ? "Double-click to read"
              : "Click to re-center · double-click to read")
    }

    // MARK: - Actions and chrome

    private func openPair(_ edge: DocumentWeb.Edge) {
        guard let from = model.index.byID[edge.fromID],
              let to = model.index.byID[edge.toID] else { return }
        model.openTranspointing(from: from.doc, to: to.doc)
    }

    private func legend(for web: DocumentWeb) -> some View {
        let rels = Array(Set(web.edges.map { $0.rel ?? "link" })).sorted()
        return HStack(spacing: 12) {
            Text("\(web.nodes.count) documents · \(web.edges.count) connections")
            ForEach(rels, id: \.self) { rel in
                HStack(spacing: 4) {
                    Circle()
                        .fill(RelStyle.color(for: rel == "link" ? nil : rel))
                        .frame(width: 7, height: 7)
                    Text(rel)
                }
            }
            Text("click to re-center · double-click to read · dot for parallel")
                .foregroundStyle(.tertiary)
        }
        .font(.caption)
        .foregroundStyle(.secondary)
        .padding(.horizontal, 12)
        .padding(.vertical, 6)
        .background(.regularMaterial, in: Capsule())
        .padding(.bottom, 10)
    }

    // MARK: - Geometry

    /// A straight edge shortened at both ends so it meets card borders, with
    /// an arrowhead showing link direction.
    private static func edgePath(from: CGPoint, to: CGPoint, shorten: CGFloat = 54) -> Path? {
        let dx = to.x - from.x
        let dy = to.y - from.y
        let length = hypot(dx, dy)
        guard length > shorten * 2 + 8 else { return nil }
        let ux = dx / length
        let uy = dy / length
        let start = CGPoint(x: from.x + ux * shorten, y: from.y + uy * shorten)
        let end = CGPoint(x: to.x - ux * shorten, y: to.y - uy * shorten)

        var path = Path()
        path.move(to: start)
        path.addLine(to: end)

        let angle = atan2(uy, ux)
        let arrow: CGFloat = 7
        let left = CGPoint(x: end.x - arrow * CGFloat(cos(angle - 0.5)),
                           y: end.y - arrow * CGFloat(sin(angle - 0.5)))
        let right = CGPoint(x: end.x - arrow * CGFloat(cos(angle + 0.5)),
                            y: end.y - arrow * CGFloat(sin(angle + 0.5)))
        path.move(to: left)
        path.addLine(to: end)
        path.addLine(to: right)
        return path
    }
}

extension DocumentWebView {
    /// The Connections view as an exchangeable module: document list in the
    /// content column, the web (map or columns-in-space) as the detail.
    @MainActor static let module = LibraryViewModule(
        id: "connections",
        name: "Connections",
        systemImage: "point.3.connected.trianglepath.dotted",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(DocumentWebView()) },
        hidesDocumentList: true
    )
}

/// The open view: full documents standing as columns in space, with lines
/// running to the exact passages that are cited — as Ted Nelson draws it.
struct WebSpaceView: View {
    @Environment(AppModel.self) private var model
    let docs: [LiquidDoc]

    var body: some View {
        let connections = ParallelReading.spaceConnections(among: docs)
        ScrollView(.horizontal) {
            HStack(alignment: .top, spacing: 28) {
                ForEach(docs) { doc in
                    ParallelColumnView(doc: doc,
                                       anchorPrefix: doc.id,
                                       highlights: highlights(for: doc, connections: connections))
                        .frame(width: 340)
                        .background(.thickMaterial, in: RoundedRectangle(cornerRadius: 10))
                        .overlay(
                            RoundedRectangle(cornerRadius: 10)
                                .stroke(doc.id == docs.first?.id
                                        ? Color.accentColor.opacity(0.7)
                                        : Color.secondary.opacity(0.25),
                                        lineWidth: doc.id == docs.first?.id ? 1.5 : 1)
                        )
                }
            }
            .padding(24)
        }
        .overlayPreferenceValue(ParagraphAnchorKey.self) { anchors in
            SpaceBeamLayer(connections: connections, anchors: anchors)
                .allowsHitTesting(false)
        }
        .clipped()
        .overlay(alignment: .bottom) {
            if !connections.isEmpty {
                Text(connections.count == 1
                     ? "1 connection between these documents"
                     : "\(connections.count) connections between these documents")
                    .font(.caption)
                    .foregroundStyle(.secondary)
                    .padding(.horizontal, 12)
                    .padding(.vertical, 6)
                    .background(.regularMaterial, in: Capsule())
                    .padding(.bottom, 10)
            }
        }
    }

    private func highlights(for doc: LiquidDoc, connections: [SpaceConnection]) -> [String: Color] {
        var result: [String: Color] = [:]
        for connection in connections {
            if connection.fromDocID == doc.id, let paragraphID = connection.fromParagraphID {
                result[paragraphID] = RelStyle.color(for: connection.rel)
            }
            if connection.toDocID == doc.id, let paragraphID = connection.toParagraphID {
                result[paragraphID] = RelStyle.color(for: connection.rel)
            }
        }
        return result
    }
}

/// Draws paragraph-precise beams among any number of document columns.
struct SpaceBeamLayer: View {
    let connections: [SpaceConnection]
    let anchors: [String: Anchor<CGRect>]

    var body: some View {
        GeometryReader { proxy in
            ForEach(connections) { connection in
                if let fromAnchor = anchors["\(connection.fromDocID):\(connection.fromParagraphID ?? "#header")"],
                   let toAnchor = anchors["\(connection.toDocID):\(connection.toParagraphID ?? "#header")"] {
                    beamPath(from: proxy[fromAnchor], to: proxy[toAnchor])
                        .stroke(RelStyle.color(for: connection.rel).opacity(0.5),
                                style: StrokeStyle(lineWidth: 2.2, lineCap: .round))
                }
            }
        }
    }

    private func beamPath(from: CGRect, to: CGRect) -> Path {
        // Leave from the edge facing the target column.
        let leftToRight = from.midX <= to.midX
        let start = CGPoint(x: leftToRight ? from.maxX : from.minX, y: from.midY)
        let end = CGPoint(x: leftToRight ? to.minX : to.maxX, y: to.midY)
        let bend = max(24, abs(end.x - start.x) * 0.4) * (leftToRight ? 1 : -1)
        var path = Path()
        path.move(to: start)
        path.addCurve(to: end,
                      control1: CGPoint(x: start.x + bend, y: start.y),
                      control2: CGPoint(x: end.x - bend, y: end.y))
        path.addEllipse(in: CGRect(x: start.x - 3, y: start.y - 3, width: 6, height: 6))
        path.addEllipse(in: CGRect(x: end.x - 3, y: end.y - 3, width: 6, height: 6))
        return path
    }
}

