import SwiftUI

/// The most-cited paragraphs across the library — the sentences the
/// community keeps pointing at. Clicking one opens the document scrolled
/// to that paragraph with the flash highlight.
struct HotParagraphsView: View {
    @Environment(AppModel.self) private var model

    var body: some View {
        let hotParagraphs = model.hotParagraphs
        List {
            ForEach(hotParagraphs) { hot in
                Button {
                    model.openInLibrary(hot.doc, fragment: hot.paragraph.id)
                } label: {
                    HStack(alignment: .top, spacing: 10) {
                        Text("\(hot.citations.count)")
                            .font(.headline.monospacedDigit())
                            .frame(minWidth: 24)
                            .padding(.vertical, 5)
                            .padding(.horizontal, 4)
                            .background(.quaternary, in: RoundedRectangle(cornerRadius: 6))
                            .help(hot.citations.count == 1 ? "Cited by 1 document" : "Cited by \(hot.citations.count) documents")
                        VStack(alignment: .leading, spacing: 3) {
                            Text(hot.paragraph.displayText)
                                .lineLimit(3)
                            Text("\(hot.doc.title) · \(hot.doc.displayAuthor) · ¶\(hot.paragraph.id)")
                                .font(.caption)
                                .foregroundStyle(.secondary)
                                .lineLimit(1)
                            citingLine(for: hot)
                        }
                    }
                    .padding(.vertical, 3)
                    .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
            }
        }
        .overlay {
            if hotParagraphs.isEmpty {
                ContentUnavailableView {
                    Label(model.searchText.isEmpty ? "No Cited Paragraphs" : "No Results",
                          systemImage: "quote.bubble")
                } description: {
                    Text("Paragraphs appear here once documents cite them directly (links with a fragment).")
                }
            }
        }
    }

    @ViewBuilder
    private func citingLine(for hot: HotParagraph) -> some View {
        let names = hot.citations
            .compactMap { model.index.byID[$0.fromID]?.doc.title }
        if !names.isEmpty {
            Text("Cited in: \(names.joined(separator: ", "))")
                .font(.caption2)
                .foregroundStyle(.tertiary)
                .lineLimit(1)
        }
    }
}

extension HotParagraphsView {
    /// The Hot Paragraphs view as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "hot-paragraphs",
        name: "Hot Paragraphs",
        systemImage: "quote.bubble",
        makeContent: { AnyView(HotParagraphsView()) }
    )
}

lift-weave.source:
import SwiftUI

/// The Lift Weave: the Weave's figure for lifted words. Every knot is a
/// person's contribution — an extract (a statement lifted out of a
/// transcript into a letter of its own) or a transcript — grouped around
/// the wheel by whose words they are, and every thread runs from an
/// extract back to the transcript it was lifted from. The same canvas as
/// the Weave: hover to flare, drag to spin, click to read.
struct LiftWeaveView: View {
    @Environment(AppModel.self) private var model

    /// An extract is a document declared `extract`, or — lifted before the
    /// type existed — one carrying someone's words with a statement-scoped
    /// citation back to its source.
    static func isExtract(_ doc: LiquidDoc) -> Bool {
        if doc.documentType == LiquidDoc.DocumentType.extract.rawValue { return true }
        return doc.onBehalfOf != nil
            && doc.links.contains { $0.rel == DocumentRelation.cites.rawValue && $0.fragment != nil }
    }

    var body: some View {
        let woven = build()
        if woven.data.nodes.isEmpty {
            ContentUnavailableView(
                "Nothing Lifted Yet",
                systemImage: "quote.opening",
                description: Text("Lift a statement out of a transcript (click a speaker's name) and the thread from the extract back to its transcript appears here.")
            )
        } else {
            WeaveCanvas(data: woven.data,
                        onOpen: { open(id: $0) },
                        title: "The Lift Weave",
                        subtitle: "\(woven.extracts) extracts · \(woven.transcripts) transcripts")
        }
    }

    /// Library and published copies together, deduplicated — extracts
    /// usually live in Published before they reach the community folder.
    private func allDocs() -> [LiquidDoc] {
        var seen: Set<String> = []
        var docs: [LiquidDoc] = []
        for doc in model.index.byID.values.map(\.doc) + model.drafts.published
        where seen.insert(doc.id).inserted {
            docs.append(doc)
        }
        return docs
    }

    private func build() -> (data: WeaveData, extracts: Int, transcripts: Int) {
        let docs = allDocs()
        let byID = Dictionary(docs.map { ($0.id, $0) }, uniquingKeysWith: { a, _ in a })
        let extracts = docs.filter(Self.isExtract)

        // Each extract's way back: its citation, followed through revision
        // chains to the transcript's latest form.
        var sourceOf: [String: String] = [:]
        for extract in extracts {
            guard let link = extract.links.first(where: { $0.rel == DocumentRelation.cites.rawValue })
            else { continue }
            let sourceID = model.index.latestRevision(of: LiquidAddress.canonical(link.to))
            if byID[sourceID] != nil { sourceOf[extract.id] = sourceID }
        }
        let transcripts = Set(sourceOf.values).compactMap { byID[$0] }

        // Everyone on the wheel by whose words the knot carries: extracts
        // under their speaker, transcripts under their author — the same
        // person-shaped wheel as the Weave itself.
        struct Knot {
            let doc: LiquidDoc
            let person: String
            let isTranscript: Bool
        }
        let knots = extracts.map { Knot(doc: $0, person: $0.onBehalfOf ?? $0.author, isTranscript: false) }
            + transcripts.map { Knot(doc: $0, person: $0.author, isTranscript: true) }
        let byPerson = Dictionary(grouping: knots, by: \.person)
        let people = byPerson.keys.sorted {
            (byPerson[$0]?.count ?? 0, $1) > (byPerson[$1]?.count ?? 0, $0)
        }
        var liftedFrom: [String: Int] = [:]
        for source in sourceOf.values { liftedFrom[source, default: 0] += 1 }

        var data = WeaveData()
        var indexByID: [String: Int] = [:]
        for (personIndex, person) in people.enumerated() {
            let hue = Double(personIndex) / Double(max(people.count, 1))
            let theirs = (byPerson[person] ?? []).sorted { $0.doc.created < $1.doc.created }
            let start = data.nodes.count
            for knot in theirs {
                indexByID[knot.doc.id] = data.nodes.count
                data.nodes.append(WeaveNode(id: knot.doc.id,
                                            title: knot.doc.title,
                                            author: person,
                                            weight: knot.isTranscript ? liftedFrom[knot.doc.id] ?? 0 : 0,
                                            hue: hue))
            }
            if data.nodes.count > start {
                data.authorArcs.append((person, hue, start...(data.nodes.count - 1)))
            }
        }
        for (extractID, sourceID) in sourceOf {
            guard let from = indexByID[extractID], let to = indexByID[sourceID] else { continue }
            data.edges.append(WeaveEdge(from: from, to: to))
        }
        return (data, extracts.count, transcripts.count)
    }

    private func open(id: String) {
        if let entry = model.index.byID[id] {
            model.openInLibrary(entry.doc)
        } else if let published = model.drafts.published.first(where: { $0.id == id }) {
            model.sidebarSelection = .published
            model.open(published)
        }
    }
}

extension LiftWeaveView {
    /// The Lift Weave as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "lift-weave",
        name: "The Lift Weave",
        systemImage: "quote.opening",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(LiftWeaveView()) },
        hidesDocumentList: true
    )
}

open-questions.source:
import SwiftUI
import FoundationModels

/// Defaults for the Open Questions view. Runs entirely on-device (Apple
/// Intelligence); no text leaves the Mac. The prompt is editable in
/// Settings → AI.
nonisolated enum OpenQuestions {

    static let defaultPrompt = """
    You are reading a community of thinkers' documents to surface the open questions: what is genuinely unresolved and still being worked out across these documents. Questions the community is asking — explicitly or between the lines — not questions you would ask about the documents.

    How to read the material: each document begins with a == line giving its title, author, date, and address. A following Relations: line is metadata — typed links between documents — treat it as structure, never as prose. Anything resembling Visual-Meta or BibTeX (@{...} markers, key = {value} fields) is metadata about a document, not content; disregard it as text even if fragments appear.

    Name between three and eight open questions, most alive first. Each needs: the question itself, phrased in one sentence as the community would ask it; one sentence on where the thinking currently stands; and the addresses of the documents that raise it or bear on it, copied exactly from their == lines. Prefer questions several documents circle around. A question one document has already settled is not open. Never invent an address.
    """
}

/// One open question as the model returns it; addresses are verified
/// against the index before display.
@Generable
nonisolated struct GeneratedQuestion {
    @Guide(description: "The open question itself, one sentence, phrased as the community would ask it")
    var question: String
    @Guide(description: "One sentence on where the community's thinking on it currently stands")
    var status: String
    @Guide(description: "Addresses of the documents that raise this question or bear on it, copied exactly from the == lines, e.g. f.hegla.093000k")
    var addresses: [String]
}

@Generable
nonisolated struct GeneratedQuestionList {
    @Guide(description: "The open questions across the documents, most alive first")
    var questions: [GeneratedQuestion]
}

/// What the community has not settled yet: the on-device model reads the
/// library and names the live questions. Each unfurls to the documents
/// that raise it.
struct OpenQuestionsView: View {
    @Environment(AppModel.self) private var model
    @AppStorage(AppSettings.aiOpenQuestionsPromptKey) private var prompt = OpenQuestions.defaultPrompt
    @State private var questions: [ResolvedQuestion] = []
    @State private var hasRun = false
    @State private var isRunning = false
    @State private var errorText: String?
    @State private var unfurled: Set<String> = []

    struct ResolvedQuestion: Identifiable {
        let question: String
        let status: String
        let entries: [IndexEntry]
        var id: String { question }
    }

    var body: some View {
        Group {
            switch SystemLanguageModel.default.availability {
            case .available:
                content
            case .unavailable(let reason):
                ContentUnavailableView {
                    Label("Apple Intelligence Unavailable", systemImage: "questionmark.circle")
                } description: {
                    Text("Open Questions uses the on-device model, so no text leaves this Mac. \(describe(reason))")
                }
            }
        }
    }

    private var content: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 12) {
                HStack(spacing: 10) {
                    Button {
                        run()
                    } label: {
                        Label(isRunning ? "Reading…" : (hasRun ? "Find Questions Again" : "Find Open Questions"),
                              systemImage: "questionmark.circle")
                    }
                    .disabled(isRunning)
                    if isRunning {
                        ProgressView()
                            .controlSize(.small)
                    }
                    Spacer()
                }
                if let errorText {
                    Text(errorText)
                        .font(.callout)
                        .foregroundStyle(.red)
                }
                if !hasRun, !isRunning {
                    Text("The on-device model reads every document in the library and names what the community is still working out — the questions no document has settled. Each opens to its documents. The prompt is yours: Settings → AI.")
                        .font(.callout)
                        .foregroundStyle(.secondary)
                } else if hasRun, questions.isEmpty, !isRunning {
                    Text("No open questions grounded in library documents came back. Try again, or adjust the prompt in Settings → AI.")
                        .font(.callout)
                        .foregroundStyle(.secondary)
                }
                ForEach(questions) { question in
                    questionRow(question)
                }
            }
            .frame(maxWidth: 620, alignment: .leading)
            .frame(maxWidth: .infinity)
            .padding(20)
        }
    }

    @ViewBuilder
    private func questionRow(_ question: ResolvedQuestion) -> some View {
        Button {
            withAnimation(.snappy) {
                if unfurled.contains(question.id) {
                    unfurled.remove(question.id)
                } else {
                    unfurled.insert(question.id)
                }
            }
        } label: {
            HStack(alignment: .firstTextBaseline, spacing: 7) {
                Image(systemName: unfurled.contains(question.id) ? "chevron.down" : "chevron.right")
                    .font(.caption)
                    .foregroundStyle(.secondary)
                Text(question.question)
                    .font(.system(size: 16, weight: .bold, design: .serif))
                    .multilineTextAlignment(.leading)
                Text("\(question.entries.count)")
                    .font(.caption.monospacedDigit())
                    .foregroundStyle(.secondary)
                    .padding(.horizontal, 6)
                    .padding(.vertical, 1)
                    .background(.quaternary, in: Capsule())
            }
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .padding(.top, 6)
        Text(question.status)
            .font(.callout)
            .foregroundStyle(.secondary)
            .padding(.leading, 18)
        if unfurled.contains(question.id) {
            ForEach(question.entries) { entry in
                Button {
                    model.openInLibrary(entry.doc)
                } label: {
                    VStack(alignment: .leading, spacing: 1) {
                        Text(entry.doc.title)
                        Text("\(entry.doc.displayAuthor) · \(entry.doc.listedDateText)")
                            .font(.caption)
                            .foregroundStyle(.secondary)
                    }
                    .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
                .padding(.leading, 36)
                .padding(.vertical, 2)
            }
        }
    }

    // MARK: - Running the model

    private func describe(_ reason: SystemLanguageModel.Availability.UnavailableReason) -> String {
        switch reason {
        case .deviceNotEligible:
            return "This Mac does not support Apple Intelligence."
        case .modelNotReady:
            return "The model is still preparing; try again shortly."
        default:
            return "Enable Apple Intelligence in System Settings to use it."
        }
    }

    private func run() {
        isRunning = true
        errorText = nil
        let corpus = AIInsights.corpus(from: Array(model.index.byID.values))
        guard corpus.includedCount > 0 else {
            errorText = "No text documents in the library yet."
            isRunning = false
            return
        }
        var fullPrompt = prompt
        fullPrompt += "\n\nTHE DOCUMENTS (\(corpus.includedCount) included"
        if corpus.omittedCount > 0 {
            fullPrompt += ", \(corpus.omittedCount) older omitted for space"
        }
        fullPrompt += "):\n\n" + corpus.text
        let request = fullPrompt
        Task {
            do {
                let session = LanguageModelSession()
                let response = try await session.respond(to: request, generating: GeneratedQuestionList.self)
                questions = resolve(response.content.questions)
                unfurled = []
                hasRun = true
            } catch {
                errorText = "The model could not respond: \(error.localizedDescription)"
            }
            isRunning = false
        }
    }

    /// Grounding: unknown addresses are dropped; a question with no real
    /// documents left disappears with them.
    private func resolve(_ generated: [GeneratedQuestion]) -> [ResolvedQuestion] {
        generated.compactMap { question in
            var seen: Set<String> = []
            let entries = question.addresses
                .map { LiquidAddress.canonical($0) }
                .filter { seen.insert($0).inserted }
                .compactMap { model.index.byID[$0] }
            guard !entries.isEmpty else { return nil }
            return ResolvedQuestion(question: question.question, status: question.status, entries: entries)
        }
    }
}

extension OpenQuestionsView {
    /// The Open Questions view as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "open-questions",
        name: "Open Questions",
        systemImage: "questionmark.circle",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(OpenQuestionsView()) },
        hidesDocumentList: true
    )
}

the-deal.source:
import SwiftUI

/// The Deal: structured serendipity. Every other view favors the recent
/// and the cited; the Deal shuffles the whole library and deals a hand of
/// cards face-up, so a forgotten document gets the same chance as
/// yesterday's. Click a card to flip it — the back is its metadata, as a
/// card back should be. Double-click to read. Drag one card onto another
/// to play a pair: the two open in parallel reading.
struct TheDealView: View {
    @Environment(AppModel.self) private var model

    private struct Dealt: Identifiable {
        let doc: LiquidDoc
        var flipped = false
        var id: String { doc.id }
    }

    @State private var hand: [Dealt] = []
    @State private var dragOffset: CGSize = .zero
    @State private var draggingID: String?

    private static let cardSize = CGSize(width: 190, height: 264)
    private static let handSize = 5

    /// The deck: the library, minus superseded and retracted versions —
    /// the Deal re-surfaces living documents, not their retired forms.
    private var deck: [LiquidDoc] {
        model.index.byID.values.map(\.doc).filter {
            !model.index.supersededIDs.contains($0.id)
                && !model.index.retractedIDs.contains($0.id)
        }
    }

    var body: some View {
        GeometryReader { geometry in
            ZStack {
                felt
                if deck.isEmpty {
                    ContentUnavailableView("Nothing to Deal",
                                           systemImage: "suit.club",
                                           description: Text("The Deal shuffles the community library. Choose a folder with documents and deal a hand."))
                } else {
                    ForEach(Array(hand.enumerated()), id: \.element.id) { index, dealt in
                        card(dealt, at: index, in: geometry.size)
                    }
                }
            }
        }
        .overlay(alignment: .bottom) { table }
        .onAppear { if hand.isEmpty { deal() } }
    }

    // MARK: The table

    private var felt: some View {
        RadialGradient(colors: [Color(red: 0.09, green: 0.32, blue: 0.17),
                                Color(red: 0.03, green: 0.15, blue: 0.08)],
                       center: .center, startRadius: 60, endRadius: 700)
            .ignoresSafeArea()
    }

    private var table: some View {
        HStack(spacing: 14) {
            Text("\(deck.count) in the deck")
                .foregroundStyle(.white.opacity(0.55))
            Button("Deal") { deal() }
                .buttonStyle(.borderedProminent)
                .disabled(deck.isEmpty)
                .help("Shuffle the library and deal a fresh hand — every document gets an equal chance")
            Text("Click to flip · double-click to read · drag a card onto another to read the pair side by side")
                .font(.caption)
                .foregroundStyle(.white.opacity(0.4))
        }
        .padding(.horizontal, 16)
        .padding(.vertical, 10)
        .background(.black.opacity(0.25), in: Capsule())
        .padding(.bottom, 18)
    }

    private func deal() {
        withAnimation(.spring(duration: 0.55, bounce: 0.25)) {
            hand = deck.shuffled().prefix(Self.handSize).map { Dealt(doc: $0) }
            dragOffset = .zero
            draggingID = nil
        }
    }

    // MARK: The cards

    /// The hand fans across the table: each card offset from center,
    /// tilted a little, the outer ones sitting slightly lower.
    private func position(at index: Int, in size: CGSize) -> CGPoint {
        let offset = Double(index) - Double(hand.count - 1) / 2
        return CGPoint(x: size.width / 2 + offset * Self.cardSize.width * 0.82,
                       y: size.height / 2 + abs(offset) * abs(offset) * 9)
    }

    private func tilt(at index: Int) -> Angle {
        let offset = Double(index) - Double(hand.count - 1) / 2
        return .degrees(offset * 4)
    }

    @ViewBuilder
    private func card(_ dealt: Dealt, at index: Int, in size: CGSize) -> some View {
        let isDragging = draggingID == dealt.id
        ZStack {
            face(for: dealt.doc)
                .opacity(dealt.flipped ? 0 : 1)
            back(for: dealt.doc)
                .rotation3DEffect(.degrees(180), axis: (x: 0, y: 1, z: 0))
                .opacity(dealt.flipped ? 1 : 0)
        }
        .frame(width: Self.cardSize.width, height: Self.cardSize.height)
        .rotation3DEffect(.degrees(dealt.flipped ? 180 : 0), axis: (x: 0, y: 1, z: 0))
        .rotationEffect(isDragging ? .zero : tilt(at: index))
        .shadow(color: .black.opacity(0.45), radius: isDragging ? 16 : 7, y: 5)
        .position(position(at: index, in: size))
        .offset(isDragging ? dragOffset : .zero)
        .zIndex(isDragging ? 1 : 0)
        .onTapGesture(count: 2) { model.openInLibrary(dealt.doc) }
        .onTapGesture {
            withAnimation(.spring(duration: 0.5)) {
                if let i = hand.firstIndex(where: { $0.id == dealt.id }) {
                    hand[i].flipped.toggle()
                }
            }
        }
        .gesture(pairDrag(for: dealt, at: index, in: size))
        .transition(.move(edge: .bottom).combined(with: .opacity))
    }

    /// Playing a pair: drop one card onto another and the two open side by
    /// side in parallel reading, connections visible.
    private func pairDrag(for dealt: Dealt, at index: Int, in size: CGSize) -> some Gesture {
        DragGesture(minimumDistance: 6)
            .onChanged { value in
                draggingID = dealt.id
                dragOffset = value.translation
            }
            .onEnded { value in
                defer {
                    draggingID = nil
                    dragOffset = .zero
                }
                let dropped = CGPoint(x: position(at: index, in: size).x + value.translation.width,
                                      y: position(at: index, in: size).y + value.translation.height)
                for (otherIndex, other) in hand.enumerated() where other.id != dealt.id {
                    let target = position(at: otherIndex, in: size)
                    if hypot(dropped.x - target.x, dropped.y - target.y) < Self.cardSize.width * 0.55 {
                        model.openTranspointing(from: dealt.doc, to: other.doc)
                        return
                    }
                }
            }
    }

    // MARK: Faces

    /// The suit: the document's type, in card terms. Letters are hearts
    /// (correspondence), transcripts clubs (people gathered), extracts
    /// diamonds (lifted gems), RFCs spades (digging into questions).
    private func suit(for doc: LiquidDoc) -> (symbol: String, isRed: Bool, name: String) {
        let type = doc.documentType
            ?? (TranscriptsView.isTranscript(doc)
                ? LiquidDoc.DocumentType.transcript.rawValue
                : LiquidDoc.DocumentType.letter.rawValue)
        switch LiquidDoc.DocumentType(rawValue: type) {
        case .letter: return ("suit.heart.fill", true, "Letter")
        case .transcript: return ("suit.club.fill", false, "Transcript")
        case .extract: return ("suit.diamond.fill", true, "Extract")
        case .rfc: return ("suit.spade.fill", false, "RFC")
        case .some(let known): return ("rectangle.portrait.fill", false, known.displayName)
        case nil: return ("rectangle.portrait.fill", false, type)
        }
    }

    private func face(for doc: LiquidDoc) -> some View {
        let suit = suit(for: doc)
        return VStack(alignment: .leading, spacing: 0) {
            HStack {
                VStack(spacing: 1) {
                    Image(systemName: suit.symbol)
                    Text(suit.name)
                        .font(.system(size: 7, weight: .semibold))
                        .textCase(.uppercase)
                }
                Spacer()
                Text(doc.date?.yearText ?? doc.created.formatted(.dateTime.year()))
                    .font(.system(size: 10, weight: .medium).monospacedDigit())
                    .foregroundStyle(.secondary)
            }
            .font(.system(size: 15))
            .foregroundStyle(suit.isRed ? Color(red: 0.78, green: 0.1, blue: 0.14) : .black)
            Spacer(minLength: 8)
            Text(doc.title)
                .font(.system(size: 15, weight: .semibold, design: .serif))
                .lineLimit(3)
                .multilineTextAlignment(.leading)
            Text(doc.displayAuthor)
                .font(.system(size: 11))
                .foregroundStyle(.secondary)
                .lineLimit(1)
                .padding(.top, 3)
            Spacer(minLength: 8)
            Text(openingWords(of: doc))
                .font(.system(size: 10, design: .serif).italic())
                .foregroundStyle(.secondary)
                .lineLimit(4)
            Spacer(minLength: 6)
            HStack {
                Spacer()
                Image(systemName: suit.symbol)
                    .font(.system(size: 15))
                    .foregroundStyle(suit.isRed ? Color(red: 0.78, green: 0.1, blue: 0.14) : .black)
                    .rotationEffect(.degrees(180))
            }
        }
        .padding(12)
        .background(cardStock)
    }

    /// The back: the card's metadata, as a card back should be — the same
    /// facts the Visual-Meta appendix carries, made the pattern itself.
    private func back(for doc: LiquidDoc) -> some View {
        let suit = suit(for: doc)
        return VStack(spacing: 5) {
            Image(systemName: suit.symbol)
                .font(.system(size: 22))
                .padding(.bottom, 4)
            metaLine("type", suit.name.lowercased())
            metaLine("author", doc.author)
            if let onBehalfOf = doc.onBehalfOf {
                metaLine("on behalf of", onBehalfOf)
            }
            metaLine("date", doc.listedDateText)
            if !doc.attention.isEmpty {
                metaLine("attention", doc.attention.joined(separator: ", "))
            }
            metaLine("links", "\(doc.links.count) out · \(model.index.backlinks[doc.id]?.count ?? 0) in")
            metaLine("address", doc.id)
        }
        .font(.system(size: 9, design: .monospaced))
        .foregroundStyle(.white.opacity(0.92))
        .multilineTextAlignment(.center)
        .padding(14)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(
            ZStack {
                RoundedRectangle(cornerRadius: 12)
                    .fill(Color(red: 0.16, green: 0.2, blue: 0.38))
                RoundedRectangle(cornerRadius: 8)
                    .strokeBorder(.white.opacity(0.35), lineWidth: 1)
                    .padding(5)
                RoundedRectangle(cornerRadius: 6)
                    .strokeBorder(.white.opacity(0.18), lineWidth: 1)
                    .padding(9)
            }
        )
        .clipShape(RoundedRectangle(cornerRadius: 12))
    }

    private func metaLine(_ label: String, _ value: String) -> some View {
        VStack(spacing: 0) {
            Text(label)
                .foregroundStyle(.white.opacity(0.45))
            Text(value)
                .lineLimit(2)
        }
    }

    private var cardStock: some View {
        RoundedRectangle(cornerRadius: 12)
            .fill(Color(red: 0.985, green: 0.975, blue: 0.95))
            .overlay(RoundedRectangle(cornerRadius: 12).strokeBorder(.black.opacity(0.12), lineWidth: 0.5))
    }

    private func openingWords(of doc: LiquidDoc) -> String {
        doc.body?
            .first { $0.effectiveHeading == nil && !$0.displayText.isEmpty }
            .map { "“\($0.displayText.prefix(140))…”" } ?? ""
    }
}

extension TheDealView {
    /// The Deal as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "the-deal",
        name: "The Deal",
        systemImage: "suit.club",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(TheDealView()) },
        hidesDocumentList: true
    )
}

